func isRussianIPv4(ip net.IP) bool {
	p := ip.To4()
	if p == nil {
		return false
	}
	v := binary.BigEndian.Uint32(p)
	lo, hi := 0, len(russianIPv4Intervals)
	for lo < hi {
		mid := lo + (hi-lo)/2
		r := russianIPv4Intervals[mid]
		if v < r.first {
			hi = mid
		} else if v > r.last {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

func shouldBypassHost(host string) bool {
	host = strings.TrimSuffix(strings.ToLower(strings.TrimSpace(host)), ".")
	mu.Lock()
	enabled := russianBypass
	rules := append([]BypassRule(nil), bypassRules...)
	mu.Unlock()
	if !enabled || host == "" {
		return false
	}
	if ip := net.ParseIP(host); ip != nil {
		if isRussianIPv4(ip) {
			return true
		}
		for _, rule := range rules {
			if rule.Type == "ip" {
				if _, network, err := net.ParseCIDR(rule.Value); err == nil && network.Contains(ip) {
					return true
				}
			}
		}
		return false
	}
	if host == "ru" || strings.HasSuffix(host, ".ru") || host == "xn--p1ai" || strings.HasSuffix(host, ".xn--p1ai") {
		return true
	}
	for _, rule := range rules {
		if rule.Type == "domain" && domainMatches(host, strings.ToLower(rule.Value)) {
			return true
		}
		if rule.Type == "ip" {
			if _, network, err := net.ParseCIDR(rule.Value); err == nil {
				if ip := net.ParseIP(host); ip != nil && network.Contains(ip) {
					return true
				}
			}
		}
	}
	return false
}

func shouldBypassTarget(target string) bool {
	host, _, err := net.SplitHostPort(target)
	if err != nil {
		host = target
	}
	return shouldBypassHost(host)
}

func dialProtected(network, target string) (net.Conn, error) {
	mu.Lock()
	localCtx := ctx
	mu.Unlock()
	if localCtx == nil {
		localCtx = context.Background()
	}
	d := net.Dialer{
		Timeout: 15 * time.Second,
		Control: func(_, _ string, c syscall.RawConn) error {
			return c.Control(func(fd uintptr) { protectControl(fd) })
		},
	}
	return d.DialContext(localCtx, network, target)
}

func dnsQuestionDomain(packet []byte) string {
	if len(packet) < 13 || binary.BigEndian.Uint16(packet[4:6]) == 0 {
		return ""
	}
	labels := make([]string, 0, 4)
	for off := 12; off < len(packet); {
		n := int(packet[off])
		off++
		if n == 0 {
			return strings.ToLower(strings.Join(labels, "."))
		}
		if n > 63 || off+n > len(packet) {
			return ""
		}
		labels = append(labels, string(packet[off:off+n]))
		off += n
	}
	return ""
}

func shouldBypassUDP(target string, payload []byte) bool {
	if shouldBypassTarget(target) {
		return true
	}
	_, port, err := net.SplitHostPort(target)
	if err == nil && port == "53" {
		if q := dnsQuestionDomain(payload); q != "" {
			return shouldBypassHost(q)
		}
	}
	return false
}
